};

let body = {
    "pageItems": 13,
    "nbreItems": 4,
    "filter_value": "consequatur",
    "idSchool": 6,
    "idSection": 8,
    "type": "consumable",
    "expired": false
}

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre>
