</code></pre>
<pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/purchase-ordersall"
);

let headers = {
    "Authorization": "Bearer {YOUR_AUTH_KEY}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "pageItems": 16,
    "nbreItems": 5,
    "filter_value": "sit",
    "status": "delivered",
    "priority": "low",
    "supplier_id": {},
    "responsible_id": {},
